var curPanel=0;var NUM_PANELS=5;

function buildSteps(){
  var h='';
  for(var i=0;i<NUM_PANELS;i++){
    var cls='step'+(i===curPanel?' on':(i<curPanel?' done':''));
    h+='<div class="'+cls+'" data-p="'+i+'"><div class="sdot">'+STEP_K[i]+'</div><div class="slbl">'+(TH?STEPS_TH[i]:STEPS_EN[i])+'</div></div>';
    if(i<NUM_PANELS-1)h+='<div class="sline"></div>';
  }
  g('steps').innerHTML=h;
  Array.prototype.forEach.call(document.querySelectorAll('.step'),function(s){
    s.addEventListener('click',function(){goTo(parseInt(s.getAttribute('data-p'),10));});});
}
function buildDots(){
  var h='';for(var i=0;i<NUM_PANELS;i++){h+='<div class="ndot'+(i===curPanel?' on':'')+'" data-p="'+i+'"></div>';}
  g('ndots').innerHTML=h;
}
function goTo(n){
  if(n<0||n>=NUM_PANELS)return;
  document.querySelectorAll('.panel').forEach(function(p,i){p.classList.toggle('on',i===n);});
  curPanel=n;buildSteps();buildDots();
  g('nb_b').className='nbtn back'+(n===0?' hidden':'');
  g('nb_n').className='nbtn'+(n===NUM_PANELS-1?' submit':' next');
  g('nb_n').textContent=n===NUM_PANELS-1?(TH?'สร้างตัวละคร →':'Generate →'):(TH?'ถัดไป →':'Next →');
}
g('nb_b').addEventListener('click',function(){goTo(curPanel-1);});
